from django.db import migrations

SCHRITTE_SPRACHEN = [
    (1, "de"), (1, "en"),
    (2, "de"), (2, "en"),
    (3, "de"), (3, "en"),
]


def vorlagen_anlegen(apps, schema_editor):
    AngebotNachfassVorlage = apps.get_model("vertrieb", "AngebotNachfassVorlage")
    for schritt, sprache in SCHRITTE_SPRACHEN:
        AngebotNachfassVorlage.objects.update_or_create(
            schritt=schritt, sprache=sprache, defaults={},
        )


def vorlagen_entfernen(apps, schema_editor):
    AngebotNachfassVorlage = apps.get_model("vertrieb", "AngebotNachfassVorlage")
    AngebotNachfassVorlage.objects.filter(
        schritt__in=[s for s, _ in SCHRITTE_SPRACHEN],
    ).delete()


class Migration(migrations.Migration):

    dependencies = [
        ("vertrieb", "0022_emailversand_angebot_alter_emailversand_mailtyp_and_more"),
    ]

